require_once __DIR__.'/../../api/db.php';$options=getopt('',['owner-id:']);$id=$options['owner-id']??'';if(!$id)throw new InvalidArgumentException('Pass --owner-id for the existing primary master user.');$db=Database::getConnection();$s=$db->prepare('SELECT id FROM users WHERE id=:id AND is_master=1 AND owner_admin_id IS NULL AND is_locked=0 AND office7_locked=0');$s->execute(['id'=>$id]);if(!($id=$s->fetchColumn()))throw new InvalidArgumentException('An active master account is required.');$db->beginTransaction();try{$s=$db->prepare('INSERT INTO office7_control(id,owner_user_id,path_token) VALUES(1,:id,:token) ON DUPLICATE KEY UPDATE owner_user_id=VALUES(owner_user_id),path_token=VALUES(path_token),revision=revision+1');$s->execute(['id'=>$id,'token'=>bin2hex(random_bytes(32))]);logAudit($db,$id,'Host administrator','update','office7',$id,'Exclusive Office Seven owner configured; private link rotated');$db->commit();echo "Primary Office Seven account configured. Sign in and retrieve your private link from Settings.\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
